   749  pdf_obj *
   750  pdf_parse_stm_obj(fz_context *ctx, pdf_document *doc, fz_stream *file, pdf_lexbuf *buf)
   751  {
   752          pdf_token tok;
   753
   754          tok = pdf_lex(ctx, file, buf);
   755
   756          switch (tok)
   757          {
   758          case PDF_TOK_OPEN_ARRAY:
   759                  return pdf_parse_array(ctx, doc, file, buf);
   760          case PDF_TOK_OPEN_DICT:
   761                  return pdf_parse_dict(ctx, doc, file, buf);
   762          case PDF_TOK_NAME: return pdf_new_name(ctx, buf->scratch);
   763          case PDF_TOK_REAL: return pdf_new_real(ctx, buf->f);
   764          case PDF_TOK_STRING: return pdf_new_string(ctx, buf->scratch, buf->len);
   765          case PDF_TOK_TRUE: return PDF_TRUE;
   766          case PDF_TOK_FALSE: return PDF_FALSE;
   767          case PDF_TOK_NULL: return PDF_NULL;
   768          case PDF_TOK_INT: return pdf_new_int(ctx, buf->i);
   769          default: fz_throw(ctx, FZ_ERROR_SYNTAX, "unknown token in object stream");
   770          }
   771  }
