   773  pdf_obj *
   774  pdf_parse_ind_obj_or_newobj(fz_context *ctx, pdf_document *doc, fz_stream *file,
   775          int *onum, int *ogen, int64_t *ostmofs, int *try_repair, int *newobj)
   776  {
   777          pdf_obj *obj = NULL;
   778          int num = 0, gen = 0;
   779          int64_t stm_ofs;
   780          pdf_token tok;
   781          pdf_lexbuf *buf = &doc->lexbuf.base;
   782          int64_t a, b;
   783          int read_next_token = 1;
   784
   785          fz_var(obj);
   786
   787          tok = pdf_lex(ctx, file, buf);
   788          if (tok != PDF_TOK_INT)
   789          {
   790                  if (try_repair)
   791                          *try_repair = 1;
   792                  fz_throw(ctx, FZ_ERROR_SYNTAX, "expected object number");
   793          }
   794          num = buf->i;
   795          if (num < 0 || num > PDF_MAX_OBJECT_NUMBER)
   796                  fz_throw(ctx, FZ_ERROR_SYNTAX, "object number out of range");
   797
   798          tok = pdf_lex(ctx, file, buf);
   799          if (tok != PDF_TOK_INT)
   800          {
   801                  if (try_repair)
   802                          *try_repair = 1;
   803                  fz_throw(ctx, FZ_ERROR_SYNTAX, "expected generation number (%d ? obj)", num);
   804          }
   805          gen = buf->i;
   806          if (gen < 0 || gen >= 65536)
   807          {
   808                  if (try_repair)
   809                          *try_repair = 1;
   810                  fz_throw(ctx, FZ_ERROR_SYNTAX, "invalid generation number (%d)", gen);
   811          }
   812
   813          tok = pdf_lex(ctx, file, buf);
   814          if (tok == PDF_TOK_NEWOBJ && newobj)
   815          {
   816                  *newobj = 1;
   817                  if (onum) *onum = num;
   818                  if (ogen) *ogen = gen;
   819                  if (ostmofs) *ostmofs = 0;
   820                  return NULL;
   821          }
   822          if (tok != PDF_TOK_OBJ)
   823          {
   824                  if (try_repair)
   825                          *try_repair = 1;
   826                  fz_throw(ctx, FZ_ERROR_SYNTAX, "expected 'obj' keyword (%d %d ?)", num, gen);
   827          }
   828
   829          tok = pdf_lex(ctx, file, buf);
   830
   831          switch (tok)
   832          {
   833          case PDF_TOK_OPEN_ARRAY:
   834                  obj = pdf_parse_array(ctx, doc, file, buf);
   835                  break;
   836
   837          case PDF_TOK_OPEN_DICT:
   838                  obj = pdf_parse_dict(ctx, doc, file, buf);
   839                  break;
   840
   841          case PDF_TOK_NAME: obj = pdf_new_name(ctx, buf->scratch); break;
   842          case PDF_TOK_REAL: obj = pdf_new_real(ctx, buf->f); break;
   843          case PDF_TOK_STRING: obj = pdf_new_string(ctx, buf->scratch, buf->len); break;
   844          case PDF_TOK_TRUE: obj = PDF_TRUE; break;
   845          case PDF_TOK_FALSE: obj = PDF_FALSE; break;
   846          case PDF_TOK_NULL: obj = PDF_NULL; break;
   847
   848          case PDF_TOK_INT:
   849                  a = buf->i;
   850                  tok = pdf_lex(ctx, file, buf);
   851
   852                  if (tok == PDF_TOK_STREAM || tok == PDF_TOK_ENDOBJ)
   853                  {
   854                          obj = pdf_new_int(ctx, a);
   855                          read_next_token = 0;
   856                          break;
   857                  }
   858                  else if (tok == PDF_TOK_INT)
   859                  {
   860                          b = buf->i;
   861                          tok = pdf_lex(ctx, file, buf);
   862                          if (tok == PDF_TOK_R)
   863                          {
   864                                  obj = pdf_new_indirect(ctx, doc, a, b);
   865                                  break;
   866                          }
   867                  }
   868                  fz_throw(ctx, FZ_ERROR_SYNTAX, "expected 'R' keyword (%d %d R)", num, gen);
   869
   870          case PDF_TOK_ENDOBJ:
   871                  obj = PDF_NULL;
   872                  read_next_token = 0;
   873                  break;
   874
   875          default:
   876                  fz_throw(ctx, FZ_ERROR_SYNTAX, "syntax error in object (%d %d R)", num, gen);
   877          }
   878
   879          fz_try(ctx)
   880          {
   881                  if (read_next_token)
   882                          tok = pdf_lex(ctx, file, buf);
   883
   884                  if (tok == PDF_TOK_STREAM)
   885                  {
   886                          int c = fz_read_byte(ctx, file);
   887                          while (c == ' ')
   888                                  c = fz_read_byte(ctx, file);
   889                          if (c == '\r')
   890                          {
   891                                  c = fz_peek_byte(ctx, file);
   892                                  if (c != '\n')
   893                                          fz_warn(ctx, "line feed missing after stream begin marker (%d %d R)", num, gen);
   894                                  else
   895                                          fz_read_byte(ctx, file);
   896                          }
   897                          stm_ofs = fz_tell(ctx, file);
   898                  }
   899                  else if (tok == PDF_TOK_ENDOBJ)
   900                  {
   901                          stm_ofs = 0;
   902                  }
   903                  else
   904                  {
   905                          fz_warn(ctx, "expected 'endobj' or 'stream' keyword (%d %d R)", num, gen);
   906                          stm_ofs = 0;
   907                  }
   908          }
   909          fz_catch(ctx)
   910          {
   911                  pdf_drop_obj(ctx, obj);
   912                  fz_rethrow(ctx);
   913          }
   914
   915          if (onum) *onum = num;
   916          if (ogen) *ogen = gen;
   917          if (ostmofs) *ostmofs = stm_ofs;
   918
   919          return obj;
   920  }
