   302  /*
   303   * Build a filter for reading raw stream data.
   304   * This is a null filter to constrain reading to the stream length (and to
   305   * allow for other people accessing the file), followed by a decryption
   306   * filter.
   307   *
   308   * orig_num and orig_gen are used purely to seed the encryption.
   309   */
   310  static fz_stream *
   311  pdf_open_raw_filter(fz_context *ctx, fz_stream *file_stm, pdf_document *doc, pdf_obj *stmobj, int num, int *orig_num, int *orig_gen, int64_t offset)
   312  {
   313          pdf_xref_entry *x = NULL;
   314          fz_stream *null_stm, *crypt_stm;
   315          int hascrypt;
   316          int64_t len;
   317
   318          if (num > 0 && num < pdf_xref_len(ctx, doc))
   319          {
   320                  x = pdf_get_xref_entry(ctx, doc, num);
   321          }
   322          if (x == NULL)
   323          {
   324                  /* We only end up here when called from pdf_open_stream_with_offset to parse new format XRef sections. */
   325                  /* New style XRef sections must have generation number 0. */
   326                  *orig_num = num;
   327                  *orig_gen = 0;
   328          }
   329          else
   330          {
   331                  *orig_num = x->num;
   332                  *orig_gen = x->gen;
   333                  if (x->stm_buf)
   334                          return fz_open_buffer(ctx, x->stm_buf);
   335          }
   336
   337          hascrypt = pdf_stream_has_crypt(ctx, stmobj);
   338          len = pdf_dict_get_int64(ctx, stmobj, PDF_NAME(Length));
   339          if (len < 0)
   340                  len = 0;
   341          null_stm = fz_open_endstream_filter(ctx, file_stm, (uint64_t)len, offset);
   342          if (doc->crypt && !hascrypt)
   343          {
   344                  fz_try(ctx)
   345                          crypt_stm = pdf_open_crypt(ctx, null_stm, doc->crypt, *orig_num, *orig_gen);
   346                  fz_always(ctx)
   347                          fz_drop_stream(ctx, null_stm);
   348                  fz_catch(ctx)
   349                          fz_rethrow(ctx);
   350                  return crypt_stm;
   351          }
   352          return null_stm;
   353  }
