   355  /*
   356   * Construct a filter to decode a stream, constraining
   357   * to stream length and decrypting.
   358   */
   359  static fz_stream *
   360  pdf_open_filter(fz_context *ctx, pdf_document *doc, fz_stream *file_stm, pdf_obj *stmobj, int num, int64_t offset, fz_compression_params *imparams)
   361  {
   362          pdf_obj *filters = pdf_dict_geta(ctx, stmobj, PDF_NAME(Filter), PDF_NAME(F));
   363          pdf_obj *params = pdf_dict_geta(ctx, stmobj, PDF_NAME(DecodeParms), PDF_NAME(DP));
   364          int orig_num, orig_gen;
   365          fz_stream *rstm, *fstm;
   366
   367          rstm = pdf_open_raw_filter(ctx, file_stm, doc, stmobj, num, &orig_num, &orig_gen, offset);
   368          fz_try(ctx)
   369          {
   370                  if (pdf_is_name(ctx, filters))
   371                          fstm = build_filter(ctx, rstm, doc, filters, params, orig_num, orig_gen, imparams);
   372                  else if (pdf_array_len(ctx, filters) > 0)
   373                          fstm = build_filter_chain(ctx, rstm, doc, filters, params, orig_num, orig_gen, imparams);
   374                  else
   375                  {
   376                          if (imparams)
   377                                  imparams->type = FZ_IMAGE_RAW;
   378                          fstm = fz_keep_stream(ctx, rstm);
   379                  }
   380          }
